// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"A",0,1],[80,"A",0,1],[112,"REST",0,1],[208,"REST",0,1],[240,"REST",0,1],[256,"A",0,1],[288,"A",0,1],[320,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"REST",0,1],[112,"B",0,1],[144,"B",0,1],[176,"B",0,1],[208,"BRIDGE",0,1],[224,"BRIDGE",0,1],[240,"RUN",0,1],[256,"REST",0,1],[320,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[112,"REST",0,1],[208,"REST",0,1],[240,"REST",0,1],[256,"HARMONY",0,1],[320,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- snesbrass ---------------------------------------------------------------------------------
const track0 = {
  color: '#ff7aa2',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Br = \\Dly\\Big[\\tfrac{1}{2048}\\big\\lfloor 2048\\tanh\\!\\big(1.3\\,\\LP_{1.5f_c}\\LP_{f_c}(\\tfrac12\\saw g + \\tfrac12\\saw 1.006g + 0.2\\sq g)\\big)\\big\\rceil\\Big]","f_c = 900 + 3800e^{-t/0.12},\\quad g = f\\cdot 2^{\\,0.2\\min(1, (t - 0.25)^+/0.25)\\sin(2\\pi\\cdot 5.6T)/12}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = osc('saw'), b = osc('saw', 0.4), q = osc('square'), lp = filter('lp'), lp2 = filter('lp'), out = filter('lp'), gate = smooth(5), glide = smooth(12)
    const echo = delay({ time: sec * 0.5, feedback: 0.36, wet: 0.22 }), verb = reverb({ room: 0.6, damp: 0.5, wet: 0.12 })
    let n = 0
    return x => {
      const m = leadAt(x), t = x * sec, held = m ? m.τ * sec : 1
      if (m) n = m.n
      const g = hz(glide(n) + 0.2 * Math.min(1, Math.max(0, held - 0.25) / 0.25) * sin(TAU * 5.6 * t), C4), fc = 900 + 3800 * exp(-held / 0.12)
      const s = tanh(1.3 * lp2(lp(0.5 * a(g) + 0.5 * b(g * 1.006) + 0.2 * q(g), fc, 0.9), fc * 1.5)), y = out(Math.round(2048 * s) / 2048, 11000)
      return verb(...echo(...pan(0.54 * gate(m && m.u < 0.93 ? 1 : 0) * y, 0.12)))
    }
  },
}

